''','''        // postgres://user:pass@host:port/dbname -> Npgsql key/value connection string
        private static string ToNpgsqlConnectionString(string url)
        {
            var uri = new Uri(url);
            var userInfo = uri.UserInfo.Split(':', 2);
            var builder = new NpgsqlConnectionStringBuilder
            {
                Host = uri.Host.Trim('[', ']'),
                Port = uri.IsDefaultPort || uri.Port <= 0 ? 5432 : uri.Port,
                Username = Uri.UnescapeDataString(userInfo[0]),
                Password = userInfo.Length > 1 ? Uri.UnescapeDataString(userInfo[1]) : null,
                Database = uri.AbsolutePath.Trim('/') is var db && db.Length > 0 ? Uri.UnescapeDataString(db) : "postgres",
            };
            return builder.ConnectionString;
        }

        // redis://[user]:[pass]@host:port -> StackExchange.Redis options
        private static ConfigurationOptions ToRedisOptions(string url)
        {
            var uri = new Uri(url);
            var options = new ConfigurationOptions
            {
                AbortOnConnectFail = true,
                Ssl = uri.Scheme == "rediss",
            };
            options.EndPoints.Add(uri.Host.Trim('[', ']'), uri.Port > 0 ? uri.Port : 6379);
            if (!string.IsNullOrEmpty(uri.UserInfo))
            {
                var userInfo = uri.UserInfo.Split(':', 2);
                if (userInfo.Length > 1)
                {
                    if (userInfo[0].Length > 0) options.User = Uri.UnescapeDataString(userInfo[0]);
                    options.Password = Uri.UnescapeDataString(userInfo[1]);
                }
                else
                {
                    options.Password = Uri.UnescapeDataString(userInfo[0]);
                }
            }
            return options;
        }
''')
